function defTac(p){
  var t={preset:p||'equilibrata',tab:'style',
    i:{sup:true,longb:false,wings:true,slow:false,press:true,aggro:true,defline:'Molto alta',defwidth:'Pi\u00f9 stretta',
       setoff:'Inserimento in area',setdef:'Marca a zona',throwin:'Cerca il primo palo',fk:'Tiri diretti',pen:'Tiri il rigorista',oppset:'Difesa a zona'}};
  GROUPS.forEach(function(g){ g.sl.forEach(function(s){ t[s.k]=s.v; }); });
  var d=DELTA[p];
  if(d){ for(var k in d) if(t[k]!=null) t[k]=cl(t[k]+d[k],2,98); }
  if(p==='offensiva'){ t.i={sup:true,longb:false,wings:true,slow:false,press:true,aggro:true,defline:'Molto alta',defwidth:'Pi\u00f9 larga',setoff:'Tutti in area',setdef:'Marca a zona',throwin:'Gioco corto',fk:'Cross in area',pen:'Tiri il rigorista',oppset:'Difesa a zona'}; }
  if(p==='difensiva'){ t.i={sup:false,longb:true,wings:false,slow:true,press:false,aggro:false,defline:'Bassa',defwidth:'Pi\u00f9 stretta',setoff:'Pochi giocatori in area',setdef:'Marca a uomo',throwin:'Lancio lungo',fk:'Scarico corto',pen:'Tiri il rigorista',oppset:'Difesa a uomo'}; }
  return t;
}
function T(){
  if(!S.tac||S.tac.width==null||!S.tac.i) S.tac=defTac('equilibrata');
  if(!S.tac.tab) S.tac.tab='style';
  if(!S.tacCustom) S.tacCustom={};
  return S.tac;
}
function gAvg(g){ var t=T(),s=0; g.sl.forEach(function(x){ s+=+t[x.k]||0; }); return s/g.sl.length; }
function band(v,arr){ return arr[cl(Math.floor(v/(100/arr.length)),0,arr.length-1)]; }
function gVal(g){ return band(gAvg(g),g.labs); }
function styleName(){ return gVal(GBY.style); }
function styleLong(){ var g=GBY.style,n=gVal(g); return g.long[n]||''; }

function markCustom(){
  var t=T();
  if(t.preset==='equilibrata'||t.preset==='offensiva'||t.preset==='difensiva'){
    t.preset=(S.tacCustom&&S.tacCustom.c1)?'c2':'c1';
  }
  S.tacCustom=S.tacCustom||{};
  S.tacCustom[t.preset]=JSON.parse(JSON.stringify(t));
}
function tacToast(m){ try{ if(typeof toast==='function') toast(m); }catch(e){} }

