/* ---------------------------------------------------------------- cursori */
function sliderHTML(s,i){
  var t=T(), v=+t[s.k];
  return '<div class="tac-sl" style="--s:'+(i+1)+'">'+
    '<div class="tac-slh"><i class="tac-sli">'+s.ic+'</i><span>'+esc(s.t)+'</span></div>'+
    '<div class="tac-sld">'+s.d+'</div>'+
    '<div class="tac-slr">'+
      '<div class="tac-track" onpointerdown="tacDrag(event,\''+s.k+'\')">'+
        '<div class="tac-fill" id="tac-f-'+s.k+'" style="width:'+v+'%"></div>'+
        '<div class="tac-knob" id="tac-k-'+s.k+'" style="left:'+v+'%"></div>'+
      '</div>'+
      '<b class="tac-slv" id="tac-n-'+s.k+'">'+v+'</b>'+
    '</div>'+
    '<div class="tac-sll" id="tac-l-'+s.k+'">'+esc(band(v,s.labs))+'</div>'+
  '</div>';
}
window.tacDrag=function(ev,k){
  var track=ev.currentTarget; if(!track) return;
  ev.preventDefault();
  var move=function(e){
    var r=track.getBoundingClientRect();
    var v=Math.round(cl((e.clientX-r.left)/r.width*100,0,100));
    var t=T(); if(t[k]===v) return;
    t[k]=v; markCustom(); slSync(k); catSync(); quickSync(); summarySync();
  };
  var up=function(){ document.removeEventListener('pointermove',move); document.removeEventListener('pointerup',up); track.classList.remove('drag'); };
  track.classList.add('drag');
  document.addEventListener('pointermove',move); document.addEventListener('pointerup',up);
  move(ev);
};
function slSync(k){
  var t=T(), v=+t[k], s=SLBY[k];
  var f=document.getElementById('tac-f-'+k), n=document.getElementById('tac-k-'+k), num=document.getElementById('tac-n-'+k), l=document.getElementById('tac-l-'+k);
  if(f) f.style.width=v+'%';
  if(n) n.style.left=v+'%';
  if(num) num.textContent=v;
  if(l&&s) l.textContent=band(v,s.labs);
}
function catSync(){
  GROUPS.forEach(function(g){
    var e=document.getElementById('tac-v-'+g.k); if(e) e.textContent=gVal(g);
    if(g.k==='style'){ var d=document.getElementById('tac-d-style'); if(d) d.textContent=g.desc[gVal(g)]||''; }
  });
  var dd=document.getElementById('tac-pdd');
  if(dd){ var b=dd.querySelector('b'); if(b) b.textContent=PRESETS[T().preset].n;
    Array.prototype.forEach.call(dd.querySelectorAll('.tac-ddi'),function(o){ o.classList.toggle('on',o.getAttribute('data-p')===T().preset); }); }
}
function quickSync(){
  var t=T();
  Array.prototype.forEach.call(document.querySelectorAll('.tac-q[data-q]'),function(n){
    var on=(n.getAttribute('data-q')===t.preset);
    n.classList.toggle('on',on);
    var c=n.querySelector('.tac-qc'); if(c) c.innerHTML=on?IC.check:IC.chev;
  });
}
function summaryText(){
  var v=styleName(), mv=gVal(GBY.ment);
  var key=(v==='Equilibrato')?'equilibrio':(/Gegenpress|Verticale/.test(v)?'intensit\u00e0 offensiva':'solidit\u00e0');
  var l=styleLong(); l=l.charAt(0).toLowerCase()+l.slice(1);
  return 'La tua squadra gioca con <b>'+esc(key)+'</b>, '+esc(l)+' Mentalit\u00e0 <b>'+esc(mv.toLowerCase())+'</b>.';
}
function summarySync(){ var e=document.getElementById('tac-sum'); if(e) e.innerHTML=summaryText(); }

window.tacPreset=function(k){
  if(k==='c1'||k==='c2'){
    var st=S.tacCustom&&S.tacCustom[k];
    S.tac=st?JSON.parse(JSON.stringify(st)):defTac('equilibrata');
    S.tac.preset=k;
    S.tacCustom=S.tacCustom||{}; S.tacCustom[k]=JSON.parse(JSON.stringify(S.tac));
  } else { var tab=T().tab; S.tac=defTac(k); S.tac.tab=tab; }
  var mid=document.getElementById('tac-col2');
  if(mid){ mid.innerHTML=GBY[T().tab].sl.map(sliderHTML).join(''); mid.classList.remove('sw'); void mid.offsetWidth; mid.classList.add('sw'); }
  catSync(); quickSync(); summarySync();
  tacToast('Tattica applicata: '+PRESETS[S.tac.preset].n);
};
window.tacSave=function(){
  markCustom(); catSync(); quickSync();
  try{ if(typeof saveGame==='function') saveGame(); }catch(e){}
  var b=document.getElementById('tac-save'); if(b){ b.classList.remove('ok'); void b.offsetWidth; b.classList.add('ok'); }
  tacToast('Tattiche salvate');
};

