function activeList(){
  var t=T(), out=[];
  TOGS_P.forEach(function(o){ if(t.i[o[0]]) out.push(esc(o[1])); });
  if(t.i.press) out.push('Pressing alto');
  if(t.i.aggro) out.push('Aggressivit\u00e0');
  out.push('Linea difensiva: <b>'+esc(t.i.defline)+'</b>');
  out.push('Ampiezza difensiva: <b>'+esc(t.i.defwidth)+'</b>');
  return out.map(function(x,i){ return '<div class="tin-al" style="--s:'+(i+1)+'"><i>'+IC.check+'</i><span>'+x+'</span></div>'; }).join('');
}
function tinActive(){ var e=document.getElementById('tin-active'); if(e) e.innerHTML=activeList(); }
function pitchSVG(){
  var t=T(), hi=/Molto alta|Alta/.test(t.i.defline), narrow=/stretta/.test(t.i.defwidth);
  var xs=narrow?[38,60,82,104]:[28,56,88,116];
  var arrows='';
  xs.forEach(function(x,i){
    var y0=hi?86:100, len=hi?46:32;
    arrows+='<g class="tin-ar" style="--a:'+(i+1)+'"><path d="M'+x+' '+y0+' L'+x+' '+(y0-len)+'"/><path d="M'+(x-6)+' '+(y0-len+8)+' L'+x+' '+(y0-len)+' L'+(x+6)+' '+(y0-len+8)+'"/></g>';
  });
  var zones='';
  [[10,26],[48,26],[114,26]].forEach(function(z,i){ zones+='<rect class="tin-z" x="'+z[0]+'" y="24" width="'+z[1]+'" height="70" style="--a:'+(i+1)+'"/>'; });
  return '<svg class="tin-pitch" viewBox="0 0 150 118" preserveAspectRatio="xMidYMid meet">'+
    '<rect class="tin-pb" x="1" y="1" width="148" height="116"/>'+zones+
    '<g class="tin-pl"><rect x="7" y="7" width="136" height="104"/><path d="M75 7V111"/><circle cx="75" cy="59" r="17"/>'+
    '<rect x="7" y="32" width="20" height="54"/><rect x="123" y="32" width="20" height="54"/>'+
    '<rect x="7" y="45" width="8" height="28"/><rect x="135" y="45" width="8" height="28"/>'+
    '<circle cx="75" cy="59" r="1.7" fill="currentColor" stroke="none"/></g>'+arrows+
  '</svg>';
}
function tinPitch(){ var e=document.getElementById('tin-pitch'); if(e) e.innerHTML=pitchSVG(); }

function instrScreen(){
  var t=T(), anim=S._tacAnim?' anim':''; S._tacAnim=false;
  return '<div class="sq26 fm-squad tac-wrap">'+navHTML('tattiche')+
    '<div class="tac tin'+anim+'" style="--tacbg:url('+BG+')">'+
      '<div class="tac-top tin-top">'+
        '<div class="tac-ttl row">'+
          '<button class="tin-back" onclick="tacInstr(0)">'+IC.back+'</button>'+
          '<div><h1>Istruzioni aggiuntive</h1><p>Personalizza ulteriormente il comportamento della squadra con istruzioni specifiche per reparto, fase di gioco e situazioni particolari.</p></div>'+
        '</div>'+
        '<div class="tin-info"><i>'+IC.info+'</i><span>Le istruzioni aggiuntive ti permettono di definire<br>come la squadra si comporta in diverse situazioni<br>di gioco, dando pi\u00f9 libert\u00e0 al tuo stile.</span></div>'+
      '</div>'+
      '<div class="tin-body">'+
        '<div class="tin-main">'+
          '<div class="tin-sec" style="--s:1">'+
            '<div class="tin-sh"><i>'+IC.poss+'</i><div><b>Fase di possesso</b><span>Come la squadra si comporta quando ha il pallone.</span></div></div>'+
            '<div class="tin-grid">'+TOGS_P.map(togCard).join('')+'</div>'+
          '</div>'+
          '<div class="tin-sec" style="--s:2">'+
            '<div class="tin-sh"><i>'+IC.def+'</i><div><b>Fase di non possesso</b><span>Come la squadra si comporta quando non ha il pallone.</span></div></div>'+
            '<div class="tin-grid">'+
              togCard(['press','Pressing alto','Inizia a pressare pi\u00f9 lontano<br>dalla propria area.',IC.push],0)+
              togCard(['aggro','Aggressivit\u00e0','Pi\u00f9 aggressivi nei contrasti<br>e nei duelli.',IC.duel],1)+
              DDS_D.map(ddCard).join('')+
            '</div>'+
          '</div>'+
          '<div class="tin-sec" style="--s:3">'+
            '<div class="tin-sh"><i>'+IC.men+'</i><div><b>Situazioni di gioco</b><span>Comportamento in base a specifiche situazioni.</span></div></div>'+
            '<div class="tin-grid">'+DDS_S.map(ddCard).join('')+'</div>'+
          '</div>'+
          '<div class="tin-note"><i>'+IC.men+'</i><div><b>Istruzioni aggiuntive</b><span>Le istruzioni aggiuntive sono attive e influenzano il comportamento della squadra in diverse situazioni di gioco.</span></div></div>'+
        '</div>'+
        '<div class="tin-side">'+
          '<div class="tac-panel tin-panel">'+
            '<div class="tac-ph">Stile di gioco</div>'+
            '<div class="tin-style"><i>'+GBY.style.ic+'</i><b>'+esc(styleName())+'</b></div>'+
            '<div class="tin-styled">'+esc(styleLong())+'</div>'+
            '<div class="tac-ph sm">Istruzioni attive</div>'+
            '<div class="tin-active" id="tin-active">'+activeList()+'</div>'+
            '<div class="tin-pwrap" id="tin-pitch">'+pitchSVG()+'</div>'+
            '<button class="tin-reset" onclick="tacReset()"><i>'+IC.reset+'</i>Ripristina impostazioni</button>'+
          '</div>'+
          '<button class="tin-save" onclick="tacSaveInstr()"><i>'+IC.check+'</i>Salva modifiche</button>'+
        '</div>'+
      '</div>'+
    '</div></div>';
}

/* ------------------------------------------------------------------- hooks */
var oldNav=window.sq26Nav;
window.sq26Nav=function(k){
  if(k==='tattiche'){ S.sq26View='tattiche'; S._tacAnim=true; render(); return; }
  if(typeof oldNav==='function') return oldNav(k);
};
var oldRender=window.renderRosa;
window.renderRosa=function(){
  var v=S.sq26View;
  if(v==='tattiche'){ ensureTacCSS(); return tacScreen(); }
  if(v==='tattiche-istr'){ ensureTacCSS(); return instrScreen(); }
  return oldRender.apply(this,arguments);
};

/* --------------------------------------------------------------------- CSS */
function ensureTacCSS(){
  if(document.getElementById('tac30-css')) return;
  var st=document.createElement('style'); st.id='tac30-css'; st.textContent=CSS; document.head.appendChild(st);
}
